using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Threading;
using System.Security.Cryptography;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using System.Web.Script.Serialization;
using System.Runtime.InteropServices;
using System.ComponentModel;
namespace PZ3D {
 internal sealed class SaveBackupSettings {public string directory,lastRunUtc="",lastMessage="";public int retention=10;public bool afterExit;}
 internal sealed class SaveBackupAutomaticResult {public int created;public string[] warnings=new string[0];internal bool enabled;}
 internal sealed class SaveBackupRow {public string id,label,createdUtc;public long bytes;public int fileCount;public bool automatic,recovery;}
 internal sealed class SaveBackupHistory {public string saveId;public SaveBackupRow[] archives;public string[] warnings;}
 internal sealed class SaveBackupInventoryRow {public string id,name,mode,latestUtc;public int count;}
 internal sealed class SaveBackupInventory {public SaveBackupInventoryRow[] saves;public string[] warnings;}
 internal sealed class SaveWorldChange {internal string path,hash;internal long bytes;internal bool deleted;}
 internal sealed class SaveWorldEditResult {internal string recoveryId;internal bool retainedDisplaced;}
 internal sealed class SaveEditRecoveryRow {public string id,stamp,saveId,name,message;public bool supported;}
 internal sealed class SaveEditRecovery {public bool pending;public SaveEditRecoveryRow[] entries;public string[] warnings;}
 // Archives belong to one installation/user/save identity. Neither UI IDs nor ZIP
 // entry names are ever accepted as filesystem paths without independent checks.
 static class SaveBackups {
  sealed class Item {public string path,hash;public long bytes,modifiedTicks;public bool directory;internal string identity;internal long createdTicks;internal FileAttributes attributes;}
  sealed class Manifest {public int schema=1;public string id,binding,saveId,label,createdUtc;public bool automatic,recovery;public List<Item> entries=new List<Item>();}
  sealed class Snapshot {internal List<Item> entries=new List<Item>();internal string rootIdentity;}
  // Counts are local to one phase; unknown scan totals remain indeterminate.
  sealed class FileActivity {
   readonly Context context;readonly string phase;readonly int totalFiles;readonly long totalBytes;readonly System.Diagnostics.Stopwatch clock=System.Diagnostics.Stopwatch.StartNew();long next,bytes;int files;
   internal FileActivity(Context context,string phase,int totalFiles=-1,long totalBytes=-1){this.context=context;this.phase=phase;this.totalFiles=totalFiles;this.totalBytes=totalBytes;Report(true);}
   internal void Found(Item item){if(!item.directory){files++;bytes+=item.bytes;}Report(false);}
   internal void Read(int count){bytes+=count;Report(false);}
   internal void CompleteFile(){files++;Report(false);}
   internal void Finish(){Report(true);}
   void Report(bool force){long elapsed=clock.ElapsedMilliseconds;if(!force&&elapsed<next)return;next=elapsed+100;context.Progress(-1,phase+"：已检查 "+files+(totalFiles<0?"":"/"+totalFiles)+" 个文件 · "+bytes+(totalBytes<0?"":"/"+totalBytes)+" 字节");}
  }
  sealed class EditJournal {public int schema=2;public string id,kind,binding,ownerIdentity,operationIdentity,parentIdentity,saveId,targetIdentity,stageIdentity,originalHash,replacementHash,recoveryId,phase;public bool finished;}
  sealed class RecoveryState {internal EditJournal journal;internal SaveEditRecoveryRow row;internal string operation,target,stage,displaced,targetState,stageState,displacedState,action;}
  sealed class Lease:IDisposable {readonly Mutex mutex;internal Lease(string name,CancellationToken cancellation){mutex=new Mutex(false,name);bool held=false;try{for(int elapsed=0;elapsed<5000;elapsed+=100){cancellation.ThrowIfCancellationRequested();try{held=mutex.WaitOne(100);}catch(AbandonedMutexException){held=true;}if(held)break;}if(!held)throw new IOException("存档备份正被其他窗口处理，请稍后重试。");cancellation.ThrowIfCancellationRequested();}catch{if(held)mutex.ReleaseMutex();mutex.Dispose();throw;}}public void Dispose(){mutex.ReleaseMutex();mutex.Dispose();}}
  sealed class Context {
   internal readonly Engine original,e;internal readonly string binding,game,user,data;readonly string[] roots,identities;
   internal Context(Engine value){original=value;game=Full(value.Game);user=Full(value.User);data=Full(value.Data);binding=Binding(value);roots=new[]{game,user,data};identities=roots.Select(path=>{Safe(path);return Directory.Exists(path)?Identity(path):null;}).ToArray();e=new Engine(game,user,data,value.TestMode,value.ReadSteamOptions,value.ProcessInventory);e.ManagedVersion=value.ManagedVersion;e.Progress=value.Progress;}
   internal void Check(){if(!Same(game,Full(original.Game))||!Same(user,Full(original.User))||!Same(data,Full(original.Data))||original.ManagedVersion!=e.ManagedVersion)throw new IOException("所选版本或用户目录已变化，请刷新后重试。");for(int i=0;i<roots.Length;i++){Safe(roots[i]);if(identities[i]!=null&&Identity(roots[i])!=identities[i])throw new IOException("安装、用户或启动器数据目录已被替换，请刷新后重试。");}}
   internal void Stopped(){Check();e.GuardContent();if(e.RuntimeRunning())throw new IOException("游戏仍在运行，请退出游戏后备份或恢复完整存档。");string workshop=Path.Combine(data,"workshop-rebuild.pending");Safe(workshop);if(File.Exists(workshop)||Directory.Exists(workshop))throw new IOException("工坊维护尚未恢复，请先完成恢复。");}
   internal void Progress(int value,string message){if(e.Progress!=null)e.Progress(value,message);}
  }
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=32};}
  static string Full(string path){string full=Path.GetFullPath(path),root=Path.GetPathRoot(full);return full.Length>root.Length?full.TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar):full;}
  static bool Same(string a,string b){return string.Equals(a,b,StringComparison.OrdinalIgnoreCase);}
  static void Safe(string path){LauncherMaintenance.NoReparse(path);}
  static string Hash(byte[] bytes){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  static string Binding(Engine e){return Hash(Encoding.UTF8.GetBytes(Full(e.Game).ToUpperInvariant()+"|"+Full(e.User).ToUpperInvariant()));}
  static string SettingsFile(Engine e){string p=Path.Combine(e.Data,"save-backup-settings",Binding(e)+".json");Safe(p);return p;}
  static bool Within(string path,string root){string prefix=root.EndsWith(Path.DirectorySeparatorChar.ToString(),StringComparison.Ordinal)?root:root+Path.DirectorySeparatorChar;return Same(path,root)||path.StartsWith(prefix,StringComparison.OrdinalIgnoreCase);}
  static string ValidDirectory(Engine e,string directory){if(string.IsNullOrWhiteSpace(directory)||!Path.IsPathRooted(directory))throw new IOException("请选择完整的备份目录。");string path=Full(directory);Safe(path);if(Within(path,Full(e.Game))||Within(path,Full(e.User)))throw new IOException("备份目录不能位于游戏或用户数据目录内。");if(File.Exists(path))throw new IOException("备份位置必须为目录。");return path;}
  static SaveBackupSettings ReadSettings(Engine e){var settings=LauncherNativeState.Read(SettingsFile(e),()=>new SaveBackupSettings{directory=Path.Combine(e.Data,"save-backups")});if(settings==null||settings.retention<0)throw new IOException("存档备份设置无效，未覆盖。");return settings;}
  public static SaveBackupSettings Settings(Engine e){var settings=ReadSettings(e);settings.directory=ValidDirectory(e,settings.directory);return settings;}
  public static SaveBackupSettings SaveSettings(Engine e,string directory,int retention,bool afterExit){var context=new Context(e);using(PlayProfileTransaction.Lock(context.e)){context.Check();if(retention<0)throw new IOException("自动备份保留数量须为非负整数；0 表示不限。");var settings=ReadSettings(context.e);settings.directory=ValidDirectory(context.e,directory);settings.retention=retention;settings.afterExit=afterExit;LauncherNativeState.Write(SettingsFile(context.e),settings);return settings;}}
  static string SavePath(Engine e,string saveId,bool required){if(!SaveDeletion.ValidId(saveId))throw new IOException("无效存档标识。");string root=Full(Path.Combine(e.User,"Saves")),path=Full(Path.Combine(root,saveId.Replace('/',Path.DirectorySeparatorChar)));if(!Within(path,root)||Same(path,root))throw new IOException("存档路径越界。");Safe(path);if(File.Exists(path)||required&&!Directory.Exists(path))throw new IOException("存档不存在，请刷新。");return path;}
  static string BindingRoot(Engine e,SaveBackupSettings settings){string path=Path.Combine(ValidDirectory(e,settings.directory),Binding(e).Substring(0,32));Safe(path);return path;}
  static string Namespace(Engine e,string saveId,SaveBackupSettings settings){SavePath(e,saveId,false);string path=Path.Combine(BindingRoot(e,settings),Hash(Encoding.UTF8.GetBytes(saveId)).Substring(0,32));Safe(path);return path;}
  static bool ValidId(string id){return Regex.IsMatch(id??"",@"\A[a-f0-9]{32}\z");}
  static string ArchivePath(string root,string id){if(!ValidId(id))throw new IOException("无效备份标识。");string path=Path.Combine(root,id+".zip");Safe(path);return path;}
  static IDisposable SaveLease(Engine e,string path,CancellationToken token){return new Lease("Local\\OrangeSaveProfiles-"+Hash(Encoding.UTF8.GetBytes(Path.GetFullPath(Path.Combine(path,"mods.txt")).ToUpperInvariant())),token);}
  public static SaveBackupHistory List(Engine e,string saveId){var context=new Context(e);context.Check();var settings=Settings(context.e);string root=Namespace(context.e,saveId,settings);var rows=new List<SaveBackupRow>();var warnings=new List<string>();if(Directory.Exists(root))foreach(string file in Directory.EnumerateFiles(root,"*.zip").OrderByDescending(p=>p,StringComparer.Ordinal)){string id=Path.GetFileNameWithoutExtension(file);if(!ValidId(id))continue;try{Safe(file);using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read))using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){var manifest=ReadManifest(zip,context.binding,saveId,id);rows.Add(new SaveBackupRow{id=id,label=manifest.label,createdUtc=manifest.createdUtc,bytes=manifest.entries.Where(i=>!i.directory).Sum(i=>i.bytes),fileCount=manifest.entries.Count(i=>!i.directory),automatic=manifest.automatic,recovery=manifest.recovery});}}catch(Exception ex){warnings.Add(id+"："+ex.Message);}}return new SaveBackupHistory{saveId=saveId,archives=rows.OrderByDescending(r=>r.createdUtc,StringComparer.Ordinal).ToArray(),warnings=warnings.ToArray()};}
  public static SaveBackupInventory Inventory(Engine e){
   var context=new Context(e);context.Check();string root=BindingRoot(context.e,Settings(context.e));var saves=new Dictionary<string,SaveBackupInventoryRow>(StringComparer.Ordinal);var warnings=new List<string>();
   // Discover from the owned archive namespace, not the live Saves directory:
   // a deleted or empty world must remain selectable for restoration.
   if(Directory.Exists(root))foreach(string directory in Directory.GetDirectories(root).OrderBy(p=>p,StringComparer.Ordinal)){
    string saveHash=Path.GetFileName(directory);if(!ValidId(saveHash)){warnings.Add("已跳过未知备份目录："+saveHash);continue;}
    try{Safe(directory);foreach(string file in Directory.GetFiles(directory,"*.zip").OrderBy(p=>p,StringComparer.Ordinal)){
     string id=Path.GetFileNameWithoutExtension(file);if(!ValidId(id)){warnings.Add("已跳过无效备份文件："+Path.GetFileName(file));continue;}
     try{Safe(file);using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read))using(var zip=new ZipArchive(input,ZipArchiveMode.Read)){
      var manifest=ReadManifest(zip,context.binding,null,id);if(Hash(Encoding.UTF8.GetBytes(manifest.saveId)).Substring(0,32)!=saveHash)throw new IOException("备份清单与所属存档目录不一致。");
      string latest=DateTime.Parse(manifest.createdUtc,null,System.Globalization.DateTimeStyles.RoundtripKind).ToUniversalTime().ToString("o");SaveBackupInventoryRow row;
      if(!saves.TryGetValue(manifest.saveId,out row)){string[] parts=manifest.saveId.Split('/');row=new SaveBackupInventoryRow{id=manifest.saveId,name=parts[1],mode=parts[0],latestUtc=latest};saves.Add(manifest.saveId,row);}row.count++;if(string.CompareOrdinal(latest,row.latestUtc)>0)row.latestUtc=latest;
     }}catch(Exception ex){warnings.Add(id+"："+ex.Message);}
    }}catch(Exception ex){warnings.Add(saveHash+"："+ex.Message);}
   }
   context.Check();return new SaveBackupInventory{saves=saves.Values.OrderByDescending(row=>row.latestUtc,StringComparer.Ordinal).ThenBy(row=>row.id,StringComparer.Ordinal).ToArray(),warnings=warnings.ToArray()};
  }
  public static object Create(Engine e,string saveId,string label,CancellationToken cancellation){var context=new Context(e);cancellation.ThrowIfCancellationRequested();using(PlayProfileTransaction.Lock(context.e)){string world=SavePath(context.e,saveId,true);using(SaveLease(context.e,world,cancellation)){context.Stopped();var settings=Settings(context.e);string root=Namespace(context.e,saveId,settings),id=CreateArchive(context,saveId,world,root,label,false,false,cancellation);return new{status="completed",id=id,message="完整存档备份已创建。"};}}}
  static string Label(string label){label=(label??"").Trim();if(label.Length>160||label.Any(char.IsControl))throw new IOException("备份名称须为 160 字以内的普通文字。");return label.Length==0?"手动备份":label;}
  static string CreateArchive(Context context,string saveId,string world,string root,string label,bool automatic,bool recovery,CancellationToken token){
   token.ThrowIfCancellationRequested();context.Stopped();Safe(root);Directory.CreateDirectory(root);string id=Guid.NewGuid().ToString("N"),target=ArchivePath(root,id),temporary=Path.Combine(root,".creating-"+id+".zip");var snapshot=ScanWithActivity(world,token,new FileActivity(context,"扫描存档"));var manifest=new Manifest{id=id,binding=context.binding,saveId=saveId,label=Label(label),automatic=automatic,recovery=recovery,createdUtc=DateTime.UtcNow.ToString("o"),entries=snapshot.entries};long total=snapshot.entries.Where(i=>!i.directory).Sum(i=>i.bytes),copied=0;
   try{Safe(temporary);using(var output=new FileStream(temporary,FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None)){using(var zip=new ZipArchive(output,ZipArchiveMode.Create,true,Encoding.UTF8)){foreach(var item in manifest.entries){token.ThrowIfCancellationRequested();string path=Child(world,item.path);Safe(path);if(item.directory){zip.CreateEntry("world/"+item.path+"/");continue;}var entry=zip.CreateEntry("world/"+item.path,CompressionLevel.Optimal);using(var source=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read))using(var destination=entry.Open()){item.hash=Transfer(source,destination,item.bytes,token,n=>{copied+=n;context.Progress(total==0?0:(int)Math.Min(99,copied*100.0/total),"压缩存档："+item.path);});}}
     var record=zip.CreateEntry("manifest.json",CompressionLevel.Optimal);using(var writer=new StreamWriter(record.Open(),new UTF8Encoding(false)))writer.Write(Json().Serialize(manifest));}output.Flush(true);}
    var verification=new FileActivity(context,"验证完整存档备份",snapshot.entries.Count(i=>!i.directory),total);token.ThrowIfCancellationRequested();Safe(temporary);using(var file=new FileStream(temporary,FileMode.Open,FileAccess.Read,FileShare.Read))using(var zip=new ZipArchive(file,ZipArchiveMode.Read))VerifyArchive(zip,manifest.binding,saveId,id,null,token,verification);VerifySource(world,snapshot,token,context);context.Stopped();Safe(root);Safe(target);token.ThrowIfCancellationRequested();File.Move(temporary,target);context.Progress(100,"完整存档备份已完成");return id;
   }finally{SafeDeleteFile(temporary);}
  }
  static Snapshot Scan(string root,CancellationToken token){return ScanWithActivity(root,token,null);}
  static Snapshot ScanWithActivity(string root,CancellationToken token,FileActivity activity){token.ThrowIfCancellationRequested();Safe(root);var snapshot=new Snapshot{rootIdentity=Identity(root)};Walk(root,"",snapshot.entries,token,activity);if(activity!=null)activity.Finish();return snapshot;}
  static void Walk(string root,string relative,List<Item> items,CancellationToken token,FileActivity activity){token.ThrowIfCancellationRequested();string path=relative.Length==0?root:Child(root,relative);Safe(path);if(!Directory.Exists(path))throw new IOException("存档目录在备份期间变化。");foreach(string child in Directory.GetFileSystemEntries(path).OrderBy(p=>p,StringComparer.Ordinal)){token.ThrowIfCancellationRequested();Safe(child);string name=(relative.Length==0?"":relative+"/")+Path.GetFileName(child);ValidateRelative(name);FileAttributes attributes=File.GetAttributes(child);bool directory=(attributes&FileAttributes.Directory)!=0;var info=directory?(FileSystemInfo)new DirectoryInfo(child):new FileInfo(child);info.Refresh();var item=new Item{path=name,directory=directory,bytes=directory?0:((FileInfo)info).Length,modifiedTicks=info.LastWriteTimeUtc.Ticks,createdTicks=info.CreationTimeUtc.Ticks,attributes=attributes,identity=Identity(child)};items.Add(item);if(activity!=null)activity.Found(item);if(directory)Walk(root,name,items,token,activity);}}
  static void VerifySource(string world,Snapshot expected,CancellationToken token,Context context=null){var actual=ScanWithActivity(world,token,context==null?null:new FileActivity(context,"复查原存档目录"));if(actual.rootIdentity!=expected.rootIdentity||actual.entries.Count!=expected.entries.Count)throw new IOException("存档在备份期间变化，请退出其他占用后重试。");var activity=context==null?null:new FileActivity(context,"核对原存档内容",expected.entries.Count(i=>!i.directory),expected.entries.Where(i=>!i.directory).Sum(i=>i.bytes));Action<int> progress=activity==null?null:new Action<int>(activity.Read);for(int i=0;i<actual.entries.Count;i++){var a=actual.entries[i];var b=expected.entries[i];if(a.path!=b.path||a.directory!=b.directory||a.bytes!=b.bytes||a.modifiedTicks!=b.modifiedTicks||a.createdTicks!=b.createdTicks||a.attributes!=b.attributes||a.identity!=b.identity)throw new IOException("存档在备份期间变化，请重试。");if(!a.directory){string path=Child(world,a.path);Safe(path);using(var file=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read))if(Transfer(file,Stream.Null,a.bytes,token,progress)!=b.hash)throw new IOException("存档文件在备份期间变化，请重试。");if(activity!=null)activity.CompleteFile();}}if(activity!=null)activity.Finish();}
  static string Transfer(Stream input,Stream output,long expected,CancellationToken token,Action<int> progress){byte[] buffer=new byte[131072];long count=0;using(var hash=SHA256.Create()){int read;while((read=input.Read(buffer,0,buffer.Length))!=0){token.ThrowIfCancellationRequested();if(read>expected-count)throw new IOException("备份条目大小与清单不一致。");output.Write(buffer,0,read);hash.TransformBlock(buffer,0,read,null,0);count+=read;if(progress!=null)progress(read);}token.ThrowIfCancellationRequested();if(count!=expected)throw new IOException("备份条目未完整读取。");hash.TransformFinalBlock(new byte[0],0,0);return BitConverter.ToString(hash.Hash).Replace("-","").ToLowerInvariant();}}
  static void ValidateRelative(string relative){if(string.IsNullOrEmpty(relative)||relative.Contains('\\')||relative.StartsWith("/",StringComparison.Ordinal)||relative.Any(char.IsControl))throw new IOException("备份条目路径无效。");foreach(string part in relative.Split('/'))if(part.Length==0||part=="."||part==".."||part.EndsWith(".",StringComparison.Ordinal)||part.EndsWith(" ",StringComparison.Ordinal)||part.IndexOfAny(Path.GetInvalidFileNameChars())>=0||Regex.IsMatch(part,@"\A(?:CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|\z)",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant))throw new IOException("备份条目路径无效。");}
  static string Child(string root,string relative){ValidateRelative(relative);string path=Full(Path.Combine(root,relative.Replace('/',Path.DirectorySeparatorChar)));if(!Within(path,Full(root))||Same(path,Full(root)))throw new IOException("备份条目路径越界。");Safe(path);return path;}
  // ZipArchiveEntry.Length is untrusted central-directory metadata. Limit the
  // decompressed stream itself, including a one-byte probe after the boundary.
  static string ReadManifestText(ZipArchiveEntry entry,long metadataBudget){
   long expected=entry.Length;if(expected<0||expected>metadataBudget||expected>int.MaxValue)throw new IOException("备份清单大小与归档条目不一致。");
   using(var input=entry.Open())using(var output=new MemoryStream()){byte[] buffer=new byte[8192];long total=0;while(true){long remaining=Math.Min(expected-total,metadataBudget-total);int requested=(int)Math.Min(buffer.Length,remaining+1);int read=input.Read(buffer,0,requested);if(read==0)break;if(read>expected-total||read>metadataBudget-total)throw new IOException("备份清单实际大小超出声明或元数据范围。");output.Write(buffer,0,read);total+=read;}
    if(total!=expected)throw new IOException("备份清单未完整读取。");byte[] bytes=output.ToArray();int start=bytes.Length>=3&&bytes[0]==239&&bytes[1]==187&&bytes[2]==191?3:0;return new UTF8Encoding(false,true).GetString(bytes,start,bytes.Length-start);
   }
  }
  static Manifest ReadManifest(ZipArchive zip,string binding,string saveId,string id){var entries=zip.Entries.Where(e=>e.FullName=="manifest.json").ToArray();if(entries.Length!=1)throw new IOException("备份缺少唯一清单。");long metadataBudget=4096L+zip.Entries.Sum(entry=>512L+6L*entry.FullName.Length);if(entries[0].Length>metadataBudget)throw new IOException("备份清单大小与归档条目不一致。");Manifest m;try{m=Json().Deserialize<Manifest>(ReadManifestText(entries[0],metadataBudget));}catch(Exception ex){throw new IOException("备份清单无法读取。",ex);}DateTime created;if(m==null||m.schema!=1||m.id!=id||m.binding!=binding||saveId!=null&&m.saveId!=saveId||!SaveDeletion.ValidId(m.saveId)||m.entries==null||m.entries.Any(i=>i==null)||m.automatic&&m.recovery||!DateTime.TryParse(m.createdUtc,null,System.Globalization.DateTimeStyles.RoundtripKind,out created)||Label(m.label)!=m.label)throw new IOException("备份身份或清单无效。");var known=new Dictionary<string,Item>(StringComparer.OrdinalIgnoreCase);foreach(var item in m.entries){ValidateRelative(item.path);if(known.ContainsKey(item.path)||item.bytes<0||item.directory&&(item.bytes!=0||item.hash!=null)||!item.directory&&!Regex.IsMatch(item.hash??"",@"\A[a-f0-9]{64}\z")||item.modifiedTicks<DateTime.MinValue.Ticks||item.modifiedTicks>DateTime.MaxValue.Ticks)throw new IOException("备份清单条目无效。");known.Add(item.path,item);}foreach(var item in m.entries){string parent=item.path;while(parent.Contains('/')){parent=parent.Substring(0,parent.LastIndexOf('/'));Item p;if(!known.TryGetValue(parent,out p)||!p.directory)throw new IOException("备份目录结构不完整。");}}return m;}
  static Manifest VerifyArchive(ZipArchive zip,string binding,string saveId,string id,string destination,CancellationToken token,FileActivity activity=null){var manifest=ReadManifest(zip,binding,saveId,id);var declared=manifest.entries.ToDictionary(i=>"world/"+i.path+(i.directory?"/":""),StringComparer.Ordinal);var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);Action<int> progress=activity==null?null:new Action<int>(activity.Read);foreach(var entry in zip.Entries){token.ThrowIfCancellationRequested();if(!seen.Add(entry.FullName)||((entry.ExternalAttributes>>16)&0xF000)==0xA000||(entry.ExternalAttributes&(int)FileAttributes.ReparsePoint)!=0)throw new IOException("备份含重复或链接条目。");if(entry.FullName=="manifest.json")continue;Item item;if(!declared.TryGetValue(entry.FullName,out item)||entry.Length!=item.bytes)throw new IOException("备份包含未声明或大小错误的条目。");if(destination!=null){string path=Child(destination,item.path);if(item.directory){Safe(path);Directory.CreateDirectory(path);}else {Safe(Path.GetDirectoryName(path));Directory.CreateDirectory(Path.GetDirectoryName(path));Safe(path);using(var input=entry.Open())using(var output=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None)){if(Transfer(input,output,item.bytes,token,progress)!=item.hash)throw new IOException("备份内容校验失败。");output.Flush(true);}Safe(path);File.SetLastWriteTimeUtc(path,new DateTime(item.modifiedTicks,DateTimeKind.Utc));}}else if(!item.directory)using(var input=entry.Open())if(Transfer(input,Stream.Null,item.bytes,token,progress)!=item.hash)throw new IOException("备份内容校验失败。");if(!item.directory&&activity!=null)activity.CompleteFile();}if(seen.Count!=declared.Count+1||declared.Keys.Any(k=>!seen.Contains(k)))throw new IOException("备份内容不完整。");if(activity!=null)activity.Finish();return manifest;}
  public static object Restore(Engine e,string saveId,string backupId,bool confirmed,CancellationToken cancellation){
