  public static object Delete(Engine e,string saveId,string backupId,bool confirmed){if(!confirmed)throw new IOException("删除备份需要明确确认。");var context=new Context(e);using(PlayProfileTransaction.Lock(context.e)){context.Check();string root=Namespace(context.e,saveId,Settings(context.e)),file=ArchivePath(root,backupId);using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read))using(var zip=new ZipArchive(input,ZipArchiveMode.Read))ReadManifest(zip,context.binding,saveId,backupId);context.Check();Safe(file);File.Delete(file);return new{status="completed",id=backupId,message="所选存档备份已删除。"};}}
  internal static string ExitIdentity(Engine e){Safe(e.Game);Safe(e.User);Safe(e.Data);return Binding(e)+":"+Identity(e.Game)+":"+Identity(e.User)+":"+Identity(e.Data);}
  internal static void ReportAutomatic(Engine e,string message){using(PlayProfileTransaction.Lock(e)){var settings=Settings(e);settings.lastRunUtc=DateTime.UtcNow.ToString("o");settings.lastMessage=message;LauncherNativeState.Write(SettingsFile(e),settings);}}
  internal static object AfterExit(Engine e,CancellationToken cancellation){SaveBackupAutomaticResult result;try{result=RunAfterExit(e,cancellation);}catch(Exception ex){try{ReportAutomatic(e,"自动备份未完成："+ex.Message);}catch{}throw;}if(result.enabled)ReportAutomatic(e,"已自动备份 "+result.created+" 个存档。"+(result.warnings.Length==0?"":"未完成："+string.Join("；",result.warnings)));return result;}
  static SaveBackupAutomaticResult RunAfterExit(Engine e,CancellationToken cancellation){
   var context=new Context(e);int count=0;var warnings=new List<string>();using(PlayProfileTransaction.Lock(context.e)){var settings=Settings(context.e);if(!settings.afterExit)return new SaveBackupAutomaticResult();context.Stopped();string saves=Path.Combine(context.user,"Saves");Safe(saves);if(Directory.Exists(saves))foreach(string mode in Directory.GetDirectories(saves)){Safe(mode);foreach(string save in Directory.GetDirectories(mode)){Safe(save);string name=Path.GetFileName(save),id=Path.GetFileName(mode)+"/"+name;if(!SaveDeletion.ValidId(id))continue;try{using(SaveLease(context.e,save,cancellation)){context.Stopped();string root=Namespace(context.e,id,settings);CreateArchive(context,id,save,root,"退出游戏后自动备份",true,false,cancellation);count++;if(settings.retention>0){var expired=List(context.e,id).archives.Where(r=>r.automatic&&!r.recovery).OrderByDescending(r=>r.createdUtc,StringComparer.Ordinal).Skip(settings.retention).ToArray();foreach(var row in expired){cancellation.ThrowIfCancellationRequested();string file=ArchivePath(root,row.id);using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read))using(var zip=new ZipArchive(input,ZipArchiveMode.Read)){var m=ReadManifest(zip,context.binding,id,row.id);if(!m.automatic||m.recovery)throw new IOException("自动保留记录已变化。");}context.Check();Safe(file);File.Delete(file);}}}}catch(OperationCanceledException){throw;}catch(Exception ex){warnings.Add(id+"："+ex.Message);}}}}return new SaveBackupAutomaticResult{created=count,warnings=warnings.ToArray(),enabled=true};
  }
  [StructLayout(LayoutKind.Sequential)]struct FileIdentity {internal uint attributes;internal System.Runtime.InteropServices.ComTypes.FILETIME creation,access,write;internal uint volume,sizeHigh,sizeLow,links,indexHigh,indexLow;}
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern Microsoft.Win32.SafeHandles.SafeFileHandle CreateFile(string path,uint access,uint share,IntPtr security,uint disposition,uint flags,IntPtr template);
  [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetFileInformationByHandle(Microsoft.Win32.SafeHandles.SafeFileHandle handle,out FileIdentity info);
  static string Identity(string path){Safe(path);using(var handle=CreateFile(path,0,7,IntPtr.Zero,3,0x02200000,IntPtr.Zero)){FileIdentity info;if(handle.IsInvalid||!GetFileInformationByHandle(handle,out info))throw new Win32Exception(Marshal.GetLastWin32Error(),"无法核实存档路径身份。");if((info.attributes&(uint)FileAttributes.ReparsePoint)!=0)throw new IOException("拒绝重解析存档路径。");return info.volume+":"+info.indexHigh+":"+info.indexLow;}}
